using namespace std;

int main() {
    int n, length;
    scanf("%d %d", &n, &length);
    vector<pair<int, int>> busy;
    for (int e = 0; e < n; e++) {
        int m;
        scanf("%d", &m);
        while (m--) { int a, b; scanf("%d %d", &a, &b); busy.push_back({a, b}); }
    }
    sort(busy.begin(), busy.end());
    vector<pair<int, int>> merged;
