        if (!merged.empty() && a <= merged.back().second) merged.back().second = max(merged.back().second, b);
        else merged.push_back({a, b});
    }
    // Half-open intervals: a meeting may start exactly when a busy block ends.
    int current = 0;
    for (auto [a, b] : merged) {
        if (a - current >= length) { printf("%d\n", current); return 0; }
        current = max(current, b);
    }
