import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken()), length = Integer.parseInt(st.nextToken());
        List<int[]> busy = new ArrayList<>();
        for (int e = 0; e < n; e++)
            for (int m = Integer.parseInt(st.nextToken()); m > 0; m--)
                busy.add(new int[] {Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken())});
        busy.sort((x, y) -> x[0] != y[0] ? Integer.compare(x[0], y[0]) : Integer.compare(x[1], y[1]));
        List<int[]> merged = new ArrayList<>();
        for (int[] iv : busy) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1]) {
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], iv[1]);
            } else merged.add(new int[] {iv[0], iv[1]});
        }
        // Half-open intervals: a meeting may start exactly when a busy block ends.
        int current = 0;
        for (int[] iv : merged) {
            if (iv[0] - current >= length) { System.out.println(current); return; }
            current = Math.max(current, iv[1]);
        }
        System.out.println(current + length <= 1440 ? current : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n, length := next(), next()
	var busy [][2]int
	for e := 0; e < n; e++ {
		for m := next(); m > 0; m-- {
			a, b := next(), next()
			busy = append(busy, [2]int{a, b})
		}
	}
	sort.Slice(busy, func(i, j int) bool {
		if busy[i][0] != busy[j][0] {
			return busy[i][0] < busy[j][0]
		}
		return busy[i][1] < busy[j][1]
	})
	var merged [][2]int
	for _, iv := range busy {
		if len(merged) > 0 && iv[0] <= merged[len(merged)-1][1] {
			merged[len(merged)-1][1] = max(merged[len(merged)-1][1], iv[1])
		} else {
			merged = append(merged, iv)
		}
	}
	// Half-open intervals: a meeting may start exactly when a busy block ends.
	current := 0
	for _, iv := range merged {
		if iv[0]-current >= length {
			fmt.Println(current)
			return
		}
		current = max(current, iv[1])
	}
	if current+length <= 1440 {
		fmt.Println(current)
	} else {
		fmt.Println(-1)
	}
}
